using Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine;

public class GUPProductCategoryPricingAttributeAdaptor extends GUPRetailPricingAttributeAdaptor implements IHierarchicalPricingAttribute
{
    private const str containsDelimiter = ',';

}

Method.Source:
public System.Boolean Match(System.Object _value, System.String _matchingExpression)
{
    str strValue = any2Str(_value);
    if (strContains(strValue, containsDelimiter))
    {
        List idList = strSplit(strValue, ',');
        ListEnumerator enum = idList.getEnumerator();
        while (enum.moveNext())
        {
            RecId currentCategoryRecId = any2Int64(enum.current());

            if (this.MatchForSingleValue(currentCategoryRecId, _matchingExpression))
            {
                return true;
            }
        }
    }
    else
    {
        return this.MatchForSingleValue(_value, _matchingExpression);
    }

    return false;
}

public System.Boolean MatchForSingleValue(System.Object _value, System.String _matchingExpression)
{
    int64 categoryRecId = any2Int64(_value);
    EcoResCategory ecoResCategory, ecoResCategoryRelated;

    select ecoResCategory where ecoResCategory.RecId == categoryRecId;

    if (ecoResCategory.RecId)
    {
        if (strContains(_matchingExpression, containsDelimiter))
        {
            return this.DoesMatchingExpressionAsContainsSyntaxMatchValue(categoryRecId, _matchingExpression);
        }
        else
        {
            return this.IsCategoryChildOfParentCategory(categoryRecId, any2Int64(_matchingExpression));
        }
    }

    return false;
}

public Integer Compare(System.String _x1, System.String _x2)
{
    if (!strContains(_x1, containsDelimiter) && !strContains(_x2, containsDelimiter))
    {
        RecId category1 = any2Int64(_x1);
        RecId category2 = any2Int64(_x2);

        if (category1 == category2)
        {
            return 0;
        }
        else if (this.IsCategoryChildOfParentCategory(category1, category2))
        {
            return 1;
        }
        else if (this.IsCategoryChildOfParentCategory(category2, category1))
        {
            return -1;
        }
        else
        {
            throw error(strFmt('%1 %2, %3 does not holds either ascendant or children relationship.', tableStr(EcoResCategory), category1, category2));
        }
    }

    return 0;
}

private System.Boolean DoesMatchingExpressionAsContainsSyntaxMatchValue(
    RecId _categoryRecId,
    str _matchingExpression)
{
    List categoryIdList = strSplit(_matchingExpression, ',');

    ListEnumerator enum = categoryIdList.getEnumerator();

    while (enum.moveNext())
    {
        RecId currentCategoryRecId = any2Int64(enum.current());

        if (this.IsCategoryChildOfParentCategory(_categoryRecId, currentCategoryRecId))
        {
            return true;
        }
    }

    return false;
}

private System.Boolean IsCategoryChildOfParentCategory(
    RecId _categoryRecId,
    RecId _parentCategoryRecId)
{
    if (_categoryRecId == _parentCategoryRecId)
    {
        return true;
    }

    EcoResCategory ecoResCategory = EcoResCategory::find(_categoryRecId, false);

    if (ecoResCategory.RecId)
    {
        EcoResCategory ecoResCategoryAscendants;

        select RecId, NestedSetLeft, NestedSetRight from ecoResCategoryAscendants
                where   ecoResCategoryAscendants.CategoryHierarchy == ecoResCategory.CategoryHierarchy
                        && ecoResCategoryAscendants.RecId == _parentCategoryRecId;

        return (ecoResCategoryAscendants.RecId
            && ecoResCategoryAscendants.NestedSetLeft < ecoResCategory.NestedSetLeft
            && ecoResCategoryAscendants.NestedSetRight > ecoResCategory.NestedSetRight);
    }

    return false;
}
